  1	final class AVLTree {
  2	    private static final class Node {
  3	        final int key;
  4	        Node left;
  5	        Node right;
  6	        int height;
  7	
  8	        Node(int key) {
  9	            this.key = key;
 10	            this.height = 1;
 11	        }
 12	    }
 13	
 14	    private Node root;
 15	
 16	    void insert(int key) {
 17	        root = insert(root, key);
 18	    }
 19	
 20	    void insertAll(int... keys) {
 21	        for (int key : keys) {
 22	            insert(key);
 23	        }
 24	    }
 25	
 26	    static AVLTree of(int... keys) {
 27	        AVLTree tree = new AVLTree();
 28	        tree.insertAll(keys);
 29	        return tree;
 30	    }
 31	
 32	    boolean isEmpty() {
 33	        return root == null;
 34	    }
 35	
 36	    boolean isValid() {
 37	        return validate(root, Long.MIN_VALUE, Long.MAX_VALUE).valid;
 38	    }
 39	
 40	    void ensureValid() {
 41	        if (!isValid()) {
 42	            throw new IllegalStateException("Tree is not a valid AVL tree");
 43	        }
 44	    }
 45	
 46	    String preOrderString() {
 47	        StringBuilder builder = new StringBuilder();
 48	        appendPreOrder(root, builder);
 49	        return builder.toString();
 50	    }
 51	
 52	    @Override
 53	    public String toString() {
 54	        return preOrderString();
 55	    }
 56	
 57	    private static int height(Node node) {
 58	        return node == null ? 0 : node.height;
 59	    }
 60	
 61	    private static void updateHeight(Node node) {
 62	        node.height = 1 + Math.max(height(node.left), height(node.right));
 63	    }
 64	
 65	    private static int balanceFactor(Node node) {
 66	        return node == null ? 0 : height(node.left) - height(node.right);
 67	    }
 68	
 69	    private static Node rotateRight(Node pivot) {
 70	        Node newRoot = pivot.left;
 71	        Node transferredSubtree = newRoot.right;
 72	
 73	        newRoot.right = pivot;
 74	        pivot.left = transferredSubtree;
 75	
 76	        updateHeight(pivot);
 77	        updateHeight(newRoot);
 78	
 79	        return newRoot;
 80	    }
 81	
 82	    private static Node rotateLeft(Node pivot) {
 83	        Node newRoot = pivot.right;
 84	        Node transferredSubtree = newRoot.left;
 85	
 86	        newRoot.left = pivot;
 87	        pivot.right = transferredSubtree;
 88	
 89	        updateHeight(pivot);
 90	        updateHeight(newRoot);
 91	
 92	        return newRoot;
 93	    }
 94	
 95	    private static Node rebalance(Node node) {
 96	        int balance = balanceFactor(node);
 97	
 98	        if (balance > 1) {
 99	            if (balanceFactor(node.left) < 0) {
100	                node.left = rotateLeft(node.left);
101	            }
102	            return rotateRight(node);
103	        }
104	
105	        if (balance < -1) {
106	            if (balanceFactor(node.right) > 0) {
107	                node.right = rotateRight(node.right);
108	            }
109	            return rotateLeft(node);
110	        }
111	
112	        return node;
113	    }
114	
115	    private static Node insert(Node node, int key) {
116	        if (node == null) {
117	            return new Node(key);
118	        }
119	
120	        if (key < node.key) {
121	            node.left = insert(node.left, key);
122	        } else if (key > node.key) {
123	            node.right = insert(node.right, key);
124	        } else {
125	            return node;
126	        }
127	
128	        updateHeight(node);
129	        return rebalance(node);
130	    }
131	
132	    private static void appendKey(StringBuilder builder, int key) {
133	        if (builder.length() > 0) {
134	            builder.append(' ');
135	        }
136	        builder.append(key);
137	    }
138	
139	    private static void appendPreOrder(Node node, StringBuilder builder) {
140	        if (node == null) {
141	            return;
142	        }
143	
144	        appendKey(builder, node.key);
145	        appendPreOrder(node.left, builder);
146	        appendPreOrder(node.right, builder);
147	    }
148	
149	    private static ValidationResult validate(Node node, long min, long max) {
150	        if (node == null) {
151	            return ValidationResult.empty();
152	        }
153	
154	        if (node.key <= min || node.key >= max) {
155	            return ValidationResult.invalid();
156	        }
157	
158	        ValidationResult left = validate(node.left, min, node.key);
159	        if (!left.valid) {
160	            return left;
161	        }
162	
163	        ValidationResult right = validate(node.right, node.key, max);
164	        if (!right.valid) {
165	            return right;
166	        }
167	
168	        int expectedHeight = 1 + Math.max(left.height, right.height);
169	        boolean heightMatches = node.height == expectedHeight;
170	        boolean balanced = Math.abs(left.height - right.height) <= 1;
171	        return new ValidationResult(
172	                heightMatches && balanced,
173	                expectedHeight
174	        );
175	    }
176	
177	    private static final class ValidationResult {
178	        final boolean valid;
179	        final int height;
180	
181	        ValidationResult(boolean valid, int height) {
182	            this.valid = valid;
183	            this.height = height;
184	        }
185	
186	        static ValidationResult empty() {
187	            return new ValidationResult(true, 0);
188	        }
189	
190	        static ValidationResult invalid() {
191	            return new ValidationResult(false, 0);
192	        }
193	    }
194	
195	    public static void main(String[] args) {
196	        AVLTree tree = AVLTree.of(10, 20, 30, 40, 50, 25);
197	        tree.ensureValid();
198	        System.out.print(tree);
199	    }
200	}
